import type { NextConfig } from 'next'

const nextConfig: NextConfig = {
  cacheComponents: true,
}

export default nextConfig

import { cacheLife, cacheTag } from 'next/cache'
import { getAllProducts } from './db.js'

export const PRODUCTS_TAG = 'products'

export type Product = { id: number; name: string; price: number }

// Cached, tagged catalog read shared by every view that depends on catalog data.
export async function getProducts(): Promise<Product[]> {
  'use cache'
  cacheTag(PRODUCTS_TAG)
  cacheLife('hours')
  return getAllProducts()
}

import { revalidateTag } from 'next/cache'
import { getProducts } from '@/lib/products'

export default async function Page() {
  const products = await getProducts()

  async function syncCatalog() {
    'use server'
    // Stale-while-revalidate: mark the catalog stale and let it refresh in the
    // background. Admins keep working with briefly stale data instead of
    // blocking on a full recompute of thousands of SKUs.
    revalidateTag('products', 'max')
  }

  return (
    <main>
      <h1>Product Catalog</h1>

      <form action={syncCatalog}>
        <button type="submit">Sync latest catalog</button>
      </form>

      <table>
        <thead>
          <tr>
            <th>ID</th>
            <th>Name</th>
            <th>Price</th>
          </tr>
        </thead>
        <tbody>
          {products.map((product) => (
            <tr key={product.id}>
              <td>{product.id}</td>
              <td>{product.name}</td>
              <td>${product.price}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </main>
  )
}
